tool_input.command:
L=/home/runner/czaba-project/tmp/studio-real-loop/b-round-429/probe; cd $L && python3 - <<'EOF'
p='spin-probe.mjs'; s=open(p).read()
s=s.replace("""const diff = (a, b) => ({ identical: a.equals(b), changedPx: a.equals(b) ? 0 : 1 });""",
"""let diffPage = null;
const diff = async (a, b) => diffPage.evaluate(async ([x, y]) => {
  const load = (u) => new Promise((ok) => { const i = new Image(); i.onload = () => ok(i); i.src = u; });
  const [A, B] = await Promise.all([load(x), load(y)]);
  const px = (img) => { const c = document.createElement('canvas'); c.width = img.width; c.height = img.height; const g = c.getContext('2d'); g.drawImage(img, 0, 0); return g.getImageData(0, 0, c.width, c.height).data; };
  const da = px(A), db = px(B); let n = 0, max = 0;
  for (let i = 0; i < da.length; i += 4) { const d = Math.max(Math.abs(da[i]-db[i]), Math.abs(da[i+1]-db[i+1]), Math.abs(da[i+2]-db[i+2])); if (d > 40) n++; if (d > max) max = d; }
  return { changedPx: n, maxDelta: max, total: da.length / 4 };
}, ['data:image/png;base64,' + a.toString('base64'), 'data:image/png;base64,' + b.toString('base64')]);
const SPIN_PX = 6;""")
s=s.replace("const d = diff(rest, hover);","const d = await diff(rest, hover);")
s=s.replace("spinVisibleOnHover: d.changedPx > 0","spinVisibleOnHover: d.changedPx >= SPIN_PX")
s=s.replace("const p = await ctx.newPage(); p.on","diffPage = await ctx.newPage(); await diffPage.setContent('<p>diff</p>');\n    const p = await ctx.newPage(); p.on")
s=s.replace("byte equality of the right 18 px crop (identical PNG = no visual change)","decoded pixel diff of the right 18 px crop (channel delta > 40 counted; spin visible = >= 6 changed px)")
s=s.replace("px=${v.gutterHoverVsRest.changedPx}","px=${v.gutterHoverVsRest.changedPx}/max${v.gutterHoverVsRest.maxDelta}")
open(p,'w').write(s)
EOF
for t in head:5173 sketch:5174 sketch-rep:5174; do n=${t%%:*}; port=${t##*:}; rm -rf $L/$n; BASE=http://127.0.0.1:$port OUT=$L/$n node spin-probe.mjs 2>&1 | tail -2 | sed "s/^/$n /"; done
